diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..3ec09e2 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,56 @@ export interface Record {
   warns: readonly string[];
 }

+function normalizeConstraint(text: string): string {
+  const lower = text.toLowerCase();
+
+  // Keywords indicating "operational burden" constraint (don't add something that requires ongoing operations)
+  const operationalKeywords = ['ops', 'operate', 'operational', 'operations', 'always-on', 'always on', 'run', 'running', 'infrastructure', 'service', 'stateful', 'manage', 'managed', 'cache', 'component', 'tier'];
+
+  const hasOperationalKeyword = operationalKeywords.some(kw => lower.includes(kw));
+
+  if (hasOperationalKeyword) {
+    return 'operational-burden';
+  }
+
+  // For other constraints, normalize by extracting meaningful words
+  const words = lower
+    .replace(/[—.,;:!?()]/g, ' ')
+    .split(/\s+/)
+    .filter(w => w.length > 2)
+    .filter(w => !['and', 'the', 'for', 'that', 'will', 'not', 'one', 'more', 'some', 'you', 'are', 'can', 'has', 'have', 'from', 'with', 'this', 'take', 'add', 'to', 'on', 'in', 'is', 'no', 'new', 'another', 'same', 'a'].includes(w))
+    .sort()
+    .slice(0, 5);
+
+  return words.join(' ');
+}
+
 export const project = (records: readonly Record[]): string => {
+  const seen = new Set<string>();
   const lines: string[] = [];
+
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of record.ruledOut) {
+      const norm = normalizeConstraint(entry);
+      if (!seen.has(norm)) {
+        seen.add(norm);
+        lines.push(`- ruled out: ${entry}`);
+      }
+    }
+    for (const limit of record.limits) {
+      const norm = normalizeConstraint(limit);
+      if (!seen.has(norm)) {
+        seen.add(norm);
+        lines.push(`- limit: ${limit}`);
+      }
+    }
+    for (const warn of record.warns) {
+      const norm = normalizeConstraint(warn);
+      if (!seen.has(norm)) {
+        seen.add(norm);
+        lines.push(`- warn: ${warn}`);
+      }
+    }
   }
   return lines.join("\n");
 };
